import { STYLE_IDS, type StyleId } from "../data/styles";

/**
 * The game's sound clips (GDD §11, build plan M35): per-style music loops with day and night
 * variants, ambient loops, footsteps by surface and one-shot UI and interaction effects. Every
 * clip is a small Ogg/Opus file under the client's `public/assets/audio/`, generated by
 * `tools/audio/generate-audio.mjs` (procedural placeholders, listed in docs/assets-credits.md).
 *
 * Pure data: the client loads and plays the clips, the selection rules (music.ts, ambience.ts,
 * surface.ts) only ever name them by id.
 */

export const MUSIC_VARIANTS = ["day", "night"] as const;
export type MusicVariant = (typeof MUSIC_VARIANTS)[number];
export type MusicTrackId = `music.${StyleId}.${MusicVariant}`;

export const AMBIENT_LAYERS = ["river", "birds", "crickets", "chatter", "rain"] as const;
export type AmbientLayer = (typeof AMBIENT_LAYERS)[number];
export type AmbientClipId = `amb.${AmbientLayer}`;

/** Footstep surfaces: the town's grounds, the bridge and dock decks and the interior floors. */
export const SURFACES = ["grass", "dirt", "cobble", "sand", "wood", "stone", "tile"] as const;
export type Surface = (typeof SURFACES)[number];
/** Recorded variations per surface; steps cycle through them (surface.ts). */
export const FOOTSTEP_VARIANTS = 3;
export type FootstepVariant = 0 | 1 | 2;
export type FootstepClipId = `step.${Surface}.${FootstepVariant}`;

export const SFX_IDS = [
  "ui.pop",
  "ui.open",
  "ui.close",
  "door.chime",
  "coins",
  "fish.cast",
  "fish.splash",
  "fish.reel",
  "cook.sizzle",
  "pickup",
  "page",
] as const;
export type SfxId = (typeof SFX_IDS)[number];

export type AudioClipId = MusicTrackId | AmbientClipId | FootstepClipId | SfxId;
export type AudioClipKind = "music" | "ambience" | "step" | "sfx";

export interface AudioClipDef {
  id: AudioClipId;
  kind: AudioClipKind;
  /** File under `public/assets/audio/`. */
  file: string;
  /**
   * Loop length in seconds for looping clips. The player loops exactly this span of the decoded
   * buffer (`loopEnd`), so codec padding at the end never makes a gap.
   */
  loopSeconds?: number;
  /** Level of the clip before the bus volumes (the placeholders are mastered at about −3 dBFS). */
  gain: number;
}

/** Length of each music loop (seconds). Day loops are a little livelier, so shorter bars. */
export const MUSIC_LOOP_SECONDS: Readonly<Record<MusicVariant, number>> = { day: 24, night: 28 };
/** Length of each ambient loop (seconds). */
export const AMBIENT_LOOP_SECONDS: Readonly<Record<AmbientLayer, number>> = { river: 12, birds: 16, crickets: 8, chatter: 12, rain: 10 };

/** Clip levels: music sits under the voices, ambience under the music, UI pops are gentle. */
const AMBIENT_GAIN: Readonly<Record<AmbientLayer, number>> = { river: 0.55, birds: 0.45, crickets: 0.35, chatter: 0.4, rain: 0.5 };
const SURFACE_GAIN: Readonly<Record<Surface, number>> = { grass: 0.45, dirt: 0.5, cobble: 0.6, sand: 0.45, wood: 0.6, stone: 0.55, tile: 0.55 };
const SFX_GAIN: Readonly<Record<SfxId, number>> = {
  "ui.pop": 0.35,
  "ui.open": 0.4,
  "ui.close": 0.35,
  "door.chime": 0.55,
  coins: 0.6,
  "fish.cast": 0.5,
  "fish.splash": 0.6,
  "fish.reel": 0.5,
  "cook.sizzle": 0.5,
  pickup: 0.5,
  page: 0.45,
};

export function musicTrackId(style: StyleId, variant: MusicVariant): MusicTrackId {
  return `music.${style}.${variant}`;
}

export function ambientClipId(layer: AmbientLayer): AmbientClipId {
  return `amb.${layer}`;
}

/** The clip of the `n`-th variation of a surface's footstep (wraps). */
export function footstepClipId(surface: Surface, n: number): FootstepClipId {
  const v = (((Math.floor(n) % FOOTSTEP_VARIANTS) + FOOTSTEP_VARIANTS) % FOOTSTEP_VARIANTS) as FootstepVariant;
  return `step.${surface}.${v}`;
}

/** File name of a clip: dots become dashes (`music.european.day` → `music-european-day.ogg`). */
export function audioFileFor(id: AudioClipId): string {
  return `${id.replaceAll(".", "-")}.ogg`;
}

function buildCatalog(): Readonly<Record<AudioClipId, AudioClipDef>> {
  const out: Partial<Record<AudioClipId, AudioClipDef>> = {};
  const add = (def: Omit<AudioClipDef, "file">) => {
    out[def.id] = { ...def, file: audioFileFor(def.id) };
  };
  for (const style of STYLE_IDS) {
    for (const variant of MUSIC_VARIANTS) add({ id: musicTrackId(style, variant), kind: "music", loopSeconds: MUSIC_LOOP_SECONDS[variant], gain: 0.7 });
  }
  for (const layer of AMBIENT_LAYERS) add({ id: ambientClipId(layer), kind: "ambience", loopSeconds: AMBIENT_LOOP_SECONDS[layer], gain: AMBIENT_GAIN[layer] });
  for (const surface of SURFACES) {
    for (let n = 0; n < FOOTSTEP_VARIANTS; n++) add({ id: footstepClipId(surface, n), kind: "step", gain: SURFACE_GAIN[surface] });
  }
  for (const id of SFX_IDS) add({ id, kind: "sfx", gain: SFX_GAIN[id] });
  return out as Record<AudioClipId, AudioClipDef>;
}

/** Every clip, by id. */
export const AUDIO_CLIPS: Readonly<Record<AudioClipId, AudioClipDef>> = buildCatalog();

export function audioClip(id: AudioClipId): AudioClipDef | undefined {
  return Object.hasOwn(AUDIO_CLIPS, id) ? AUDIO_CLIPS[id] : undefined;
}

export function isAudioClipId(value: unknown): value is AudioClipId {
  return typeof value === "string" && Object.hasOwn(AUDIO_CLIPS, value);
}

/** Total download budget for every clip (bytes): the placeholders must stay small (GDD §9.5). */
export const AUDIO_BUDGET_BYTES = 3 * 1024 * 1024;
